MORE = [GF, SOA, RISIKO, LIEFER, RANSOM, BIA, MFA, AUDIT, PHISHING, VERSICHERUNG]


def _extend(article, extra):
    """Praxisteil vor einen abschließenden Hinweis setzen, sonst ans Ende."""
    body = article["body"]
    at = len(body) - 1 if body[-1][0] == "note" else len(body)
    body[at:at] = extra


