# Meta-Texte auf Suchergebnislänge kürzen
GF["title"] = "NIS2 für Geschäftsführer: Pflichten, Haftung | CyberSecCheck"
SOA["title"] = "Erklärung zur Anwendbarkeit (SoA) erklärt | CyberSecCheck"
LIEFER["title"] = "Lieferantenfragebögen beantworten | CyberSecCheck"
RANSOM["title"] = "Notfallplan Ransomware: die ersten 24 Stunden | CyberSecCheck"
AUDIT["desc"] = "Was ISO 27001 vom internen Audit verlangt, wie Sie Auditprogramm, Auditoren und Bericht aufsetzen und das Audit als Probelauf nutzen."
PHISHING["desc"] = "Phishing-Simulationen im Unternehmen: was Betriebsrat und Datenschutz verlangen und wie Sie auswerten, ohne Mitarbeitende bloßzustellen."
RISIKO["desc"] = "Eine Risikoanalyse, die auch kleine Unternehmen durchhalten: Kriterien, Gefährdungen, Bewertung und Behandlung nach ISO 27001."
LIEFER["desc"] = "Kunden schicken Fragebögen zur Informationssicherheit, oft wegen NIS2? So antworten Sie schnell, ehrlich und überzeugend."
MFA["desc"] = "Multi-Faktor-Authentifizierung im Unternehmen einführen: welche Konten zuerst, welche Verfahren, wie Sie Mitarbeitende mitnehmen."

# Weitere häufige Fragen (auch für Suchanfragen in Frageform)
BIA["faq"] += [("Was ist der Unterschied zwischen BIA und Risikoanalyse?", "Die BIA fragt, wie schlimm ein Ausfall wäre und wie schnell ein Prozess wieder laufen muss, egal warum er ausfällt. Die Risikoanalyse fragt, was passieren kann und wie wahrscheinlich das ist. Beide ergänzen sich: Die BIA zeigt, was besonders schützenswert ist, die Risikoanalyse, wogegen.")]
VERSICHERUNG["faq"] += [("Was passiert, wenn wir eine Frage im Antrag falsch beantwortet haben?", "Melden Sie sich bei Ihrem Versicherer oder Makler, sobald Ihnen der Fehler auffällt, und korrigieren Sie die Angabe. Je nach Vertrag und Fall können falsche Angaben den Schutz gefährden, eine frühe Korrektur ist deshalb der bessere Weg."),
                        ("Zahlt die Versicherung auch Lösegeld?", "Das regeln die Bedingungen des einzelnen Vertrags sehr unterschiedlich. Behörden raten grundsätzlich davon ab, Lösegeld zu zahlen. Klären Sie die Frage vorab mit Ihrem Versicherer oder Makler.")]
SOA["faq"] += [("Wer gibt die SoA frei?", "Üblich ist die Freigabe durch die Geschäftsführung oder die für das ISMS verantwortliche Leitung. Wichtig ist, dass die Freigabe dokumentiert ist und eine Versionsnummer und ein Datum hat.")]
AUDIT["faq"] += [("Was ist der Unterschied zwischen internem Audit und Managementbewertung?", "Das interne Audit prüft, ob das ISMS die Anforderungen erfüllt und wirksam ist. Die Managementbewertung ist die Sitzung, in der die Leitung die Ergebnisse, darunter die des Audits, bewertet und über Änderungen entscheidet."),
                 ("Dürfen wir eine Vorlage für die Checkliste verwenden?", "Ja, als Ausgangspunkt. Passen Sie sie aber an Ihre eigenen Regeln und Prozesse an. Ein Audit, das nur die Norm abfragt, übersieht, ob Ihre eigenen Vorgaben eingehalten werden.")]
LIEFER["faq"] += [("Sollten wir für Fragebögen eine eigene Vorlage anbieten?", "Das kann sinnvoll sein. Eine kurze Sicherheitsübersicht mit den wichtigsten Maßnahmen und Nachweisen beantwortet viele Fragen vorab. Manche Kunden bestehen trotzdem auf ihrem eigenen Fragebogen."),
                  ("Was ist TISAX, und brauchen wir das?", "TISAX ist ein Prüf- und Austauschverfahren der Automobilindustrie. Ob Sie es brauchen, entscheidet in der Regel Ihr Kunde aus dieser Branche. Außerhalb der Automobilindustrie spielt es kaum eine Rolle.")]
MFA["faq"] += [("Sind Passkeys sicherer als Einmalcodes?", "In der Regel ja. Passkeys und Sicherheitsschlüssel sind an die echte Webseite gebunden und lassen sich deshalb kaum über gefälschte Anmeldeseiten abgreifen. Einmalcodes können dagegen in eine Phishing-Seite eingegeben werden."),
               ("Was tun mit Konten, die von mehreren Personen genutzt werden?", "Gemeinsam genutzte Konten sind ein Risiko, weil nicht nachvollziehbar ist, wer was getan hat. Wo es geht, sollten sie durch persönliche Konten ersetzt werden. Wo nicht, helfen ein sicherer Passwortspeicher und eine klare Zuständigkeit.")]
PHISHING["faq"] += [("Dürfen wir echte Firmennamen in den Simulationen verwenden?", "Vorsicht bei Marken anderer Unternehmen und bei Behörden. Stimmen Sie das mit dem Anbieter der Plattform und gegebenenfalls juristisch ab. Szenarien ohne echte Marken funktionieren oft genauso gut.")]
RANSOM["faq"] += [("Wie oft sollten wir den Notfallplan üben?", "Mindestens einmal im Jahr und nach größeren Änderungen an IT oder Organisation. Eine Planbesprechung am Tisch dauert wenige Stunden und deckt viele Lücken auf.")]

_extend(VERSICHERUNG, [("p", "Noch ein Hinweis zur Abgrenzung: Eine Cyberversicherung ist keine Betriebsunterbrechungs- oder Elektronikversicherung im klassischen Sinn, auch wenn sich die Leistungen überschneiden können. Prüfen Sie mit Ihrem Makler, welche Risiken schon durch bestehende Verträge abgedeckt sind und wo Lücken bleiben. Doppelte Deckungen kosten Geld, fehlende Deckungen im Ernstfall noch mehr.")])
_extend(SOA, [("p", "Ein letzter Tipp: Halten Sie die Begründungen kurz und prüfbar. Ein Satz mit Verweis auf ein Risiko, eine Anforderung oder eine Entscheidung reicht. Lange Absätze in jeder Zeile machen die SoA unübersichtlich und verdecken das Wesentliche.")])
_extend(AUDIT, [("p", "Zum Schluss: Ein internes Audit, das keine Feststellungen hat, ist verdächtig. Jedes ISMS hat Verbesserungspotenzial. Ein ehrlicher Bericht mit einigen Hinweisen zeigt dem Zertifizierungsauditor, dass Ihr Audit ernsthaft war und das System lernt.")])
_extend(LIEFER, [("p", "Und schließlich: Sprechen Sie mit Ihren wichtigsten Kunden. Oft lässt sich in einem kurzen Gespräch klären, welche Nachweise wirklich gebraucht werden und welche Fragen für Ihre Leistung gar keine Rolle spielen. Das spart beiden Seiten Arbeit und schafft Vertrauen.")])
_extend(MFA, [("p", "Ein Hinweis für Unternehmen mit Produktion: Maschinen, Steuerungen und Bedienterminals lassen sich oft nicht mit MFA ausstatten. Hier helfen eine saubere Trennung des Produktionsnetzes vom Büronetz, Fernwartung nur über einen gesicherten Zugang mit MFA und eine Liste aller Zugänge, die regelmäßig überprüft wird.")])
_extend(PHISHING, [("p", "Zum Schluss: Feiern Sie die Meldungen. Wer eine verdächtige Mail meldet, egal ob Simulation oder echter Angriff, sollte eine kurze, freundliche Rückmeldung bekommen. Das stärkt genau das Verhalten, das Sie im Ernstfall brauchen.")])
